-- submissions/district-slug
-- A district's slug, for the public slug of a crash that is being published.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

select "slug"
from "districts"
where "districts"."id" = $1
limit $2;
